 quick.innerHTML=upgradeDefs.slice(0,3).map(d=>{const c=cost(d),rank=S.upgrades[d.id];return `<div class="upgrade-card"><div class="upgrade-top"><div class="upgrade-icon">${d.icon}</div><div><div class="upgrade-name">${d.name}</div><div class="upgrade-lvl">RANK ${rank}</div></div></div><div class="upgrade-desc">${d.desc}</div><div class="buy-row"><span class="cost">◈ ${fmt(c)}</span><button class="buy-btn" data-buy="${d.id}" ${S.gold<c?'disabled':''}>UPGRADE</button></div></div>`}).join('');
