@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap');
:root{--bg:#101210;--panel:#171a17;--panel2:#1d211d;--line:#2c322c;--text:#f2f1e9;--muted:#92978d;--gold:#e4b45c;--green:#a4d39b;--red:#f07866;--blue:#8eb8dd;--purple:#b99af3;--font:'DM Sans',sans-serif;--display:'Playfair Display',serif;--mono:'DM Mono',monospace}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(ellipse at 50% -20%,#272b21 0,transparent 55%),var(--bg);color:var(--text);font:14px var(--font);min-height:100vh}
