52: <script>
53: const SAVE_KEY='emberfall-idle-save-v1';
54: const BOSS_WAVE=50,MAX_ZONE=1000;
55: const enemies=[['Mossling','FOREST WANDERER','moss'],['Gloom Wolf','MOONLIT PREDATOR','wolf'],['Thornback','ANCIENT SENTINEL','thorn'],['Ashwing','CINDER HUNTER','bird'],['Rootbound','ELDER OF THE GROVE','golem'],['Hollow Knight','LOST OATHKEEPER','knight'],['Briar Witch','WILDSPELLER','witch'],['Dread Stag','KING OF THE WOOD','stag']];
56: const zoneNames=['Withered Glade','Moonlit Hollow','Thornwild Reach','Cinderfall','Elderwood','Hollow March','Witchfen','Dreadwood','Glasswater Fen','The Sunken Crown','Starfall Expanse','Ashen Frontier'];
57: const zonePrefixes=['Forgotten','Veiled','Eclipsed','Forsaken','Crimson','Silver','Shattered','Eternal','Whispering','Frostbound','Obsidian','Emberlit'];
58: const zoneSuffixes=['Vale','Basin','Wilds','Frontier','Sanctum','Wastes','Reach','Hinterlands','Crown','Deep','March','Expanse'];
59: const zoneName=zone=>zone<=zoneNames.length?`The ${zoneNames[zone-1]}`:`${zonePrefixes[Math.floor((zone-1)/zoneNames.length)%zonePrefixes.length]} ${zoneSuffixes[(zone*7+Math.floor(zone/zoneNames.length))%zoneSuffixes.length]}`;
60: const upgradeDefs=[{id:'blade',name:'Tempered Blade',icon:'⚔',desc:'Increase all attack damage by 25% per rank.',base:20,scale:1.48},{id:'training',name:'Warrior Training',icon:'♟',desc:'Gain +3 base power with every rank.',base:35,scale:1.55},{id:'fortune',name:'Lucky Charm',icon:'☘',desc:'Earn 18% more gold from every enemy.',base:45,scale:1.62},{id:'swift',name:'Swift Strikes',icon:'➶',desc:'Increase idle damage per second by 15% per rank.',base:60,scale:1.7},{id:'bounty',name:'Bounty Ledger',icon:'▤',desc:'A further 12% gold from all victories per rank.',base:110,scale:1.72},{id:'lore',name:'Field Notes',icon:'✎',desc:'Earn 10% more experience from every encounter.',base:125,scale:1.75},{id:'precision',name:'Keen Eye',icon:'◎',desc:'Gain +1.5% critical chance per rank.',base:180,scale:1.82},{id:'bossbane',name:'Wyrm-Breaker',icon:'♜',desc:'Deal 20% more damage to zone bosses per rank.',base:240,scale:1.9}];
61: const legacyDefs=[{id:'might',name:'Cinderheart',icon:'♨',desc:'+5 starting power and +10% damage per rank.',base:3,scale:1.9},{id:'wisdom',name:'Seeker’s Memory',icon:'✧',desc:'+15% gold and experience earned per rank.',base:4,scale:2},{id:'fortune',name:'Ashen Treasury',icon:'◈',desc:'+20% gold from every victory per rank.',base:5,scale:2.1}];
62: const skillDefs=[{id:'heavy',name:'Meteor Strike',icon:'☄',desc:'Deal 8× your damage instantly. Cooldown: 12 seconds.',cooldown:12},{id:'frenzy',name:'Ember Frenzy',icon:'♨',desc:'Double your attacks for 15 seconds. Cooldown: 45 seconds.',cooldown:45},{id:'fortune',name:'Golden Touch',icon:'✧',desc:'Triple gold earned for the next 30 seconds. Cooldown: 90 seconds.',cooldown:90}];
63: const questDefs=[{id:'first',name:'First Steps',desc:'Defeat 5 enemies',goal:5,reward:50,type:'kills'},{id:'hunter',name:'Beast Hunter',desc:'Defeat 25 enemies',goal:25,reward:220,type:'kills'},{id:'explorer',name:'Into the Wild',desc:'Reach zone 3',goal:3,reward:300,type:'zone'},{id:'veteran',name:'A Veteran’s Path',desc:'Reach hero level 10',goal:10,reward:500,type:'level'},{id:'wealth',name:'A Little Fortune',desc:'Collect 1,000 gold',goal:1000,reward:350,type:'goldEarned'},{id:'slayer',name:'Legendary Slayer',desc:'Defeat 100 enemies',goal:100,reward:1500,type:'kills'}];
64: const fresh=()=>({gold:0,shards:0,level:1,xp:0,power:5,kills:0,zone:1,wave:1,enemyHp:0,bossActive:false,bossReady:false,bossUntil:0,autoSkills:true,upgrades:{blade:0,training:0,fortune:0,swift:0,bounty:0,lore:0,precision:0,bossbane:0},relics:{might:0,wisdom:0,fortune:0},skills:{heavy:0,frenzy:0,fortune:0},cooldowns:{},buffs:{},claimed:[],ascensions:0,bossesDefeated:0,highestZone:1,goldEarned:0,campaignComplete:false,last:Date.now(),totalPlay:0});
65: let S=load(),activeView='adventure',toastTimer;
66: function load(){try{const d=JSON.parse(localStorage.getItem(SAVE_KEY));if(d){const s={...fresh(),...d};s.upgrades={...fresh().upgrades,...d.upgrades};s.relics={...fresh().relics,...d.relics};s.skills={...fresh().skills,...d.skills};s.cooldowns=d.cooldowns||{};s.buffs=d.buffs||{};s.claimed=d.claimed||[];s.zone=Math.max(1,Math.min(MAX_ZONE,Math.floor(s.zone||1)));s.highestZone=Math.max(s.zone,s.highestZone||s.zone);if(s.bossActive){s.bossActive=false;s.bossReady=true;s.bossUntil=0;s.wave=BOSS_WAVE-1;s.enemyHp=0}if(s.bossReady)s.wave=BOSS_WAVE-1;return s}}catch(e){}return fresh()}
67: function save(){S.last=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify(S))}catch(e){}}
68: function fmt(n){if(!Number.isFinite(n))return '∞';if(Math.abs(n)<1000)return Math.floor(n).toLocaleString();const units=['K','M','B','T','Qa','Qi','Sx','Sp','Oc','No','Dc'];let i=-1;while(n>=1000&&i<units.length-1){n/=1000;i++}return n>=1000?`${n.toExponential(2)}`:`${n.toFixed(n>=100?0:n>=10?1:2)}${units[i]}`}
69: function xpNeed(){return Math.floor(35*Math.pow(S.level,1.42))}
70: function getPower(){return (S.power+S.upgrades.training*3+S.relics.might*5)*Math.pow(1.25,S.upgrades.blade)*(1+S.ascensions*.5)*(1+S.relics.might*.1)*(1+S.skills.heavy*.08)}
71: function getDps(){return getPower()*(1+S.upgrades.swift*.15)*(S.buffs.frenzy>0?2:1)}
72: function maxHp(){return 30*Math.pow(1.31,S.zone-1)*Math.pow(1.055,S.wave-1)}
73: function bossHp(){return maxHp()*28}
74: function bossName(){return `${enemies[(S.zone*3+2)%enemies.length][0]} Overlord`}
75: function goldReward(){return Math.floor((8+S.zone*4+S.wave*2)*(1+S.upgrades.fortune*.18)*(1+S.upgrades.bounty*.12)*(1+S.relics.wisdom*.15+S.relics.fortune*.2)*(S.buffs.fortune>0?3:1))}
76: function enemy(){return enemies[(S.zone+S.wave-2)%enemies.length]}
77: function critChance(){return Math.min(75,5+S.upgrades.blade*1.2+S.upgrades.precision*1.5+S.skills.heavy*.5)}
78: function toast(msg){const el=document.createElement('div');el.className='toast';el.innerHTML=msg;document.getElementById('toastArea').replaceChildren(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),2600)}
79: function addXp(n){S.xp+=n;while(S.xp>=xpNeed()){S.xp-=xpNeed();S.level++;S.power+=2+Math.floor(S.level*.3);toast(`✨ Hero reached <strong>level ${S.level}</strong>! Power increased.`)}}
80: function spawnEnemy(){S.enemyHp=S.bossActive?bossHp():maxHp()}
81: function startBoss(){if(S.campaignComplete)return;S.bossActive=true;S.bossReady=false;S.wave=BOSS_WAVE;S.bossUntil=Date.now()+10000;spawnEnemy();toast(`☠ ${bossName()} challenges you! Defeat it within 10 seconds.`)}
